extension CareGuides {
    static let careServices = DirectoryGuide(
        cardSummary: .init(ukrainian: "Вибрати службу, порівняти обсяг і оплату, організувати заміну", german: "Dienst wählen, Umfang und Kosten vergleichen, Vertretung sichern"),
        introduction: .init(ukrainian: "Послуги залежать від землі та адреси. Розрізняйте побутову допомогу, професійний догляд і медичне лікування вдома.", german: "Angebote hängen von Bundesland und Wohnort ab. Haushaltshilfe, professionelle Pflege und medizinische Behandlung zu Hause unterscheiden."),
        sections: [
            .init("first-contact", "phone", "Перший контакт у своїй землі", "Erster Kontakt im Bundesland", "Зверніться до консультації з догляду вашої землі, Gemeinde або Bezirk і скажіть, де живе людина, який Pflegegeld-ступінь уже є та яка допомога потрібна вдень і вночі. Попросіть перелік місцевих постачальників, вільні місця, строки очікування й документи для субсидії. Нижче в застосунку відкриється регіональний контакт; якщо фактично мешкаєте в іншій землі, виберіть її вручну.", "Pflegeberatung des Bundeslandes, Gemeinde oder Bezirk kontaktieren und Wohnort, vorhandene Pflegegeldstufe sowie Hilfe am Tag und in der Nacht nennen. Lokale Anbieter, freie Plätze, Wartezeit und Unterlagen für Förderung erfragen. Unten in der App erscheint der regionale Kontakt; bei Aufenthalt in einem anderen Land dieses manuell wählen.", source: mobile),
            .init("home-help", "house", "Heimhilfe чи допомога з господарством", "Heimhilfe oder Haushaltshilfe", "Якщо складно з прибиранням, їжею, покупками чи щоденною гігієною, запитайте про Heimhilfe або Haushaltshilfe. Уточніть, які дії дозволені працівнику, тривалість кожного візиту, мінімальну кількість годин, доплату та порядок заміни. Heimhilfe не замінює медсестру для процедур. Вартість і доступність визначаються місцевою службою та правилами землі.", "Bei Schwierigkeiten mit Reinigung, Essen, Einkäufen oder täglicher Hygiene Heimhilfe oder Haushaltshilfe erfragen. Erlaubte Tätigkeiten, Besuchsdauer, Mindeststunden, Eigenbeitrag und Vertretung klären. Heimhilfe ersetzt keine Pflegefachkraft für medizinische Maßnahmen. Preis und Verfügbarkeit richten sich nach örtlichem Dienst und Landesregeln.", source: mobile),
            .init("nursing", "cross.case", "Медична допомога вдома", "Medizinische Pflege zu Hause", "Для перев’язок чи інших медичних процедур попросіть лікаря про призначення medizinische Hauskrankenpflege й уточніть покриття у страхової каси. Вона зазвичай надається до чотирьох тижнів, продовження потребує погодження каси. Довший соціальний Hauskrankenpflege організовують і оплачують за іншими регіональними правилами. Попросіть чітко вказати, яка саме послуга призначена.", "Für Verbände oder andere medizinische Maßnahmen ärztliche Verordnung für medizinische Hauskrankenpflege holen und Kassenleistung klären. Sie wird grundsätzlich bis zu vier Wochen erbracht; Verlängerung braucht Bewilligung der Kasse. Längere soziale Hauskrankenpflege wird anders organisiert und regional finanziert. Genau benennen lassen, welche Leistung verordnet wurde.", source: nursing),
            .init("discharge", "bed.double", "План після виписки з лікарні", "Plan nach dem Krankenhaus", "Ще до виписки скажіть лікарняному соціальному працівнику, якщо вдома немає безпечного догляду. Попросіть письмовий план: ліки, перев’язки, засоби, перший візит служби та контакт при погіршенні. Якщо повернення додому поки неможливе, запитайте про Übergangspflege — тимчасове місце й земельні умови фінансування; заявку та місце узгоджуйте до дня виписки.", "Noch vor Entlassung dem Spitalssozialdienst sagen, wenn zu Hause keine sichere Versorgung besteht. Schriftlichen Plan für Medikamente, Verbände, Hilfsmittel, ersten Dienstbesuch und Kontakt bei Verschlechterung verlangen. Ist Heimkehr noch nicht möglich, Übergangspflege mit befristetem Platz und Landesfinanzierung erfragen; Antrag und Platz vor dem Entlasstag klären.", source: transition),
            .init("respite", "calendar", "Тимчасовий догляд і заміна", "Kurzzeitpflege und Vertretung", "Якщо близька людина захворіла або потребує відпочинку, можна шукати Kurzzeitpflege у закладі чи Ersatzpflege вдома. Спершу перевірте вільне місце, мінімальний і максимальний строк та повну оплату. Земля може мати окрему субсидію, а Sozialministeriumservice — допомогу на документовані витрати основного доглядальника за своїми умовами. Не плутайте це з відпусткою працівника Pflegekarenz.", "Bei Krankheit oder Erholungsbedarf der Pflegeperson Kurzzeitpflege in einer Einrichtung oder Ersatzpflege zu Hause suchen. Freien Platz, Mindest- und Höchstdauer sowie Gesamtkosten zuerst klären. Das Land kann eigene Zuschüsse bieten, das Sozialministeriumservice unter seinen Voraussetzungen belegte Kosten der Hauptpflegeperson fördern. Nicht mit arbeitsrechtlicher Pflegekarenz verwechseln.", source: respite),
            .init("round-clock", "clock", "Цілодобова Betreuung: договір і дотація", "24-Stunden-Betreuung: Vertrag und Zuschuss", "Порівняйте самозайняту й найману Betreuungskraft: хто є роботодавцем, які обов’язки, заміна, проживання, нічні години, страхування та повна місячна ціна. Sozialministeriumservice перевіряє дотацію за рівнем Pflegegeld, потребою та доходом; для ступенів 3–4 потребу в цілодобовій допомозі перевіряють окремо. Заяву краще подати до початку або не пізніше місяця після початку — пізніше фінансування обмежене.", "Selbständige und angestellte Betreuungskraft vergleichen: Arbeitgeberrolle, Aufgaben, Vertretung, Unterkunft, Nachtzeiten, Versicherung und volle Monatskosten. Das Sozialministeriumservice prüft Zuschuss nach Pflegegeldstufe, Bedarf und Einkommen; bei Stufen 3–4 wird die Notwendigkeit eigens festgestellt. Antrag möglichst vor Beginn oder spätestens im Folgemonat stellen, da spätere Förderung begrenzt ist.", source: roundClock),
            .init("children", "figure.child", "Догляд за дитиною — окрема служба", "Kinderpflege ist ein eigener Dienst", "Якщо дитині потрібні ін’єкції, перев’язки, догляд після операції або підтримка при тяжкому захворюванні, шукайте mobile Kinderkrankenpflege, а не звичайну Heimhilfe для дорослих. Попросіть педіатра чи лікарню описати медичні дії та потрібні години; у регіональній консультації уточніть доступного постачальника й частку оплати. Програми і постачальники відрізняються за землею.", "Braucht ein Kind Injektionen, Verbände, Pflege nach Operation oder Hilfe bei schwerer Erkrankung, mobile Kinderkrankenpflege statt allgemeiner Heimhilfe für Erwachsene suchen. Kinderarzt oder Spital soll Maßnahmen und Stunden beschreiben; bei regionaler Beratung Anbieter und Eigenanteil erfragen. Programme und Träger unterscheiden sich je Bundesland.", source: children),
            .init("institution", "building.2", "Якщо потрібен постійний заклад", "Wenn dauerhaft ein Heim nötig ist", "Порівняйте заклади за доглядом уночі, медичним супроводом, відвідинами, доступністю, вільним місцем і письмовим Heimvertrag. Попросіть розрахунок базової плати, доплати за ступенем і особистих витрат. Зазвичай використовують пенсію, Pflegegeld та інші доходи; нестачу можуть покрити через Sozialhilfe. З 2018 року за федеральним правилом заборонено Pflegeregress на майно мешканця та родичів для таких витрат.", "Heime nach Nachtpflege, medizinischer Versorgung, Besuchen, Zugänglichkeit, freiem Platz und schriftlichem Heimvertrag vergleichen. Grundgebühr, Pflegezuschlag und persönliche Ausgaben berechnen lassen. Üblicherweise werden Pension, Pflegegeld und weitere Einkünfte eingesetzt; eine Lücke kann Sozialhilfe decken. Seit 2018 ist der Pflegeregress auf Vermögen der Bewohner und Angehörigen für diese Kosten bundesweit untersagt.", source: home),
            .init("compare", "list.bullet.rectangle", "Письмово порівняйте пропозиції", "Angebote schriftlich vergleichen", "Для кожної служби складіть одну таблицю: завдання, години на тиждень, ніч і вихідні, час очікування, заміна при хворобі, ціна до й після субсидії, строк відмови. Уточніть окремо, що оплачує страхова каса, що земля, а що ви. Pflegegeld — фіксований внесок до витрат, а не автоматична оплата всіх рахунків; попросіть остаточну письмову суму перед договором.", "Für jeden Dienst dieselbe Liste führen: Aufgaben, Wochenstunden, Nacht und Wochenende, Wartezeit, Ersatz bei Ausfall, Preis vor und nach Förderung, Kündigungsfrist. Getrennt klären, was Kasse, Land und Sie selbst zahlen. Pflegegeld ist ein pauschaler Beitrag, keine automatische Bezahlung aller Rechnungen; Endbetrag vor Vertrag schriftlich verlangen.", source: mobile)
        ], sources: [mobile, nursing, transition, respite, roundClock, children, home]
    )
}
